-- Snapshot batch 13
EXEC sys.sp_executesql N''/****** Object:  View [dbo].[vw_TopSearchKeywords]    Script Date: 9/10/2026 2:47:50 PM ******/
SET ANSI_NULLS ON'';

-- Snapshot batch 14
EXEC sys.sp_executesql N''SET QUOTED_IDENTIFIER ON'';

-- Snapshot batch 15
EXEC sys.sp_executesql N''CREATE VIEW [dbo].[vw_TopSearchKeywords]
AS
SELECT TOP 100
        [NormalizedKeyword],
        COUNT(*)          AS SearchCount,
        MIN([ResultCount]) AS MinResultCount,
        MAX([CreatedAt])   AS LastSearchedAt
FROM    [dbo].[SearchLogs]
WHERE   [CreatedAt] >= DATEADD(DAY, -30, GETDATE())
        AND [NormalizedKeyword] IS NOT NULL
GROUP BY [NormalizedKeyword]
ORDER BY COUNT(*) DESC;'';

