SELECT N''HOAN TAT - ShoegroupDB da san sang'' AS KetQua, DB_NAME() AS TenDatabase, 46 AS SoBang, 577 AS SoDongDuLieu, 36 AS SoChiMucBoSung;';
BEGIN TRY
  IF DB_ID(N'ShoegroupDB') IS NOT NULL
  BEGIN
    EXEC sys.sp_executesql N'ALTER DATABASE [ShoegroupDB] SET SINGLE_USER WITH ROLLBACK IMMEDIATE; DROP DATABASE [ShoegroupDB];';
  END;
  EXEC sys.sp_executesql N'CREATE DATABASE [ShoegroupDB] COLLATE SQL_Latin1_General_CP1_CI_AS;';
  EXEC sys.sp_executesql N'ALTER DATABASE [ShoegroupDB] SET RECOVERY SIMPLE; ALTER DATABASE [ShoegroupDB] SET PAGE_VERIFY CHECKSUM; ALTER DATABASE [ShoegroupDB] SET AUTO_CLOSE OFF; ALTER DATABASE [ShoegroupDB] SET AUTO_SHRINK OFF; ALTER DATABASE [ShoegroupDB] SET RECURSIVE_TRIGGERS OFF; ALTER DATABASE [ShoegroupDB] SET READ_COMMITTED_SNAPSHOT OFF; ALTER DATABASE [ShoegroupDB] SET ALLOW_SNAPSHOT_ISOLATION OFF;';
  IF (SELECT compatibility_level FROM sys.databases WHERE name=N'ShoegroupDB')<140
    EXEC sys.sp_executesql N'ALTER DATABASE [ShoegroupDB] SET COMPATIBILITY_LEVEL = 140;';
  SET @InstallSql = N'USE [ShoegroupDB]; ' + @InstallSql;
  EXEC sys.sp_executesql @InstallSql;
END TRY
BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;
